[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles',[string]$OutputPath='ES/Output/WebPageStudio/webpagestudio-migration-report-v3.json')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$migration=& (Join-Path $root 'ES/Automation/WebPageStudio/New-ESWebPageStudioMigrationReport.ps1') -BundlesDirectory $BundlesDirectory|ConvertFrom-Json;$offline=& (Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioAllOfflinePackages.ps1') -BundlesDirectory $BundlesDirectory|ConvertFrom-Json;$offlineSummary=[pscustomobject]@{packageCount=$offline.packageCount;passedPackageCount=$offline.passedPackageCount;failedPackageCount=$offline.failedPackageCount;status=$offline.status;reportRecordType=$offline.recordType};$migration|Add-Member -NotePropertyName offlinePackages -NotePropertyValue $offlineSummary -Force;$out=[IO.Path]::GetFullPath((Join-Path $root $OutputPath));if(-not $out.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'OutputPath must remain under project root.'};[IO.File]::WriteAllText($out,($migration|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));$relativeReport=$out.Replace($root,'').Replace('\','/');$migration|Add-Member -NotePropertyName reportPath -NotePropertyValue $relativeReport -Force;$migration|ConvertTo-Json -Depth 15
